import{_ as a,o as n,c as p,a0 as l}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"正则的扩展","description":"","frontmatter":{},"headers":[],"relativePath":"es6/regex.md","filePath":"es6/regex.md","lastUpdated":1791573371000}'),e={name:"es6/regex.md"};function o(c,s,r,t,i,y){return n(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="正则的扩展" tabindex="-1">正则的扩展 <a class="header-anchor" href="#正则的扩展" aria-label="Permalink to &quot;正则的扩展&quot;">​</a></h1><h2 id="regexp-构造函数" tabindex="-1">RegExp 构造函数 <a class="header-anchor" href="#regexp-构造函数" aria-label="Permalink to &quot;RegExp 构造函数&quot;">​</a></h2><p>在 ES5 中，<code>RegExp</code>构造函数的参数有两种情况。</p><p>第一种情况是，参数是字符串，这时第二个参数表示正则表达式的修饰符（flag）。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> regex </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xyz&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;i&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 等价于</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> regex </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /xyz/</span><span style="color:#D73A49;">i</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第二种情况是，参数是一个正则表示式，这时会返回一个原有正则表达式的拷贝。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> regex </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/xyz/</span><span style="color:#D73A49;">i</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 等价于</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> regex </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /xyz/</span><span style="color:#D73A49;">i</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>但是，ES5 不允许此时使用第二个参数添加修饰符，否则会报错。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> regex </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/xyz/</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;i&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// Uncaught TypeError: Cannot supply flags when constructing one RegExp from another</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>ES6 改变了这种行为。如果<code>RegExp</code>构造函数第一个参数是一个正则对象，那么可以使用第二个参数指定修饰符。而且，返回的正则表达式会忽略原有的正则表达式的修饰符，只使用新指定的修饰符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/abc/</span><span style="color:#D73A49;">ig</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;i&#39;</span><span style="color:#24292E;">).flags</span></span>
<span class="line"><span style="color:#6A737D;">// &quot;i&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，原有正则对象的修饰符是<code>ig</code>，它会被第二个参数<code>i</code>覆盖。</p><h2 id="字符串的正则方法" tabindex="-1">字符串的正则方法 <a class="header-anchor" href="#字符串的正则方法" aria-label="Permalink to &quot;字符串的正则方法&quot;">​</a></h2><p>字符串对象共有 4 个方法，可以使用正则表达式：<code>match()</code>、<code>replace()</code>、<code>search()</code>和<code>split()</code>。</p><p>ES6 将这 4 个方法，在语言内部全部调用<code>RegExp</code>的实例方法，从而做到所有与正则相关的方法，全都定义在<code>RegExp</code>对象上。</p><ul><li><code>String.prototype.match</code> 调用 <code>RegExp.prototype[Symbol.match]</code></li><li><code>String.prototype.replace</code> 调用 <code>RegExp.prototype[Symbol.replace]</code></li><li><code>String.prototype.search</code> 调用 <code>RegExp.prototype[Symbol.search]</code></li><li><code>String.prototype.split</code> 调用 <code>RegExp.prototype[Symbol.split]</code></li></ul><h2 id="u-修饰符" tabindex="-1">u 修饰符 <a class="header-anchor" href="#u-修饰符" aria-label="Permalink to &quot;u 修饰符&quot;">​</a></h2><p>ES6 对正则表达式添加了<code>u</code>修饰符，含义为“Unicode 模式”，用来正确处理大于<code>\\uFFFF</code>的 Unicode 字符。也就是说，会正确处理四个字节的 UTF-16 编码。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">\\uD83D</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;</span><span style="color:#005CC5;">\\uD83D\\uDC2A</span><span style="color:#032F62;">&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">\\uD83D</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;</span><span style="color:#005CC5;">\\uD83D\\uDC2A</span><span style="color:#032F62;">&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，<code>\\uD83D\\uDC2A</code>是一个四个字节的 UTF-16 编码，代表一个字符。但是，ES5 不支持四个字节的 UTF-16 编码，会将其识别为两个字符，导致第二行代码结果为<code>true</code>。加了<code>u</code>修饰符以后，ES6 就会识别其为一个字符，所以第一行代码结果为<code>false</code>。</p><p>一旦加上<code>u</code>修饰符号，就会修改下面这些正则表达式的行为。</p><p><strong>（1）点字符</strong></p><p>点（<code>.</code>）字符在正则表达式中，含义是除了换行符以外的任意单个字符。对于码点大于<code>0xFFFF</code>的 Unicode 字符，点字符不能识别，必须加上<code>u</code>修饰符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> s </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;𠮷&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">.</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// false</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">.</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>上面代码表示，如果不添加<code>u</code>修饰符，正则表达式就会认为字符串为两个字符，从而匹配失败。</p><p><strong>（2）Unicode 字符表示法</strong></p><p>ES6 新增了使用大括号表示 Unicode 字符，这种表示法在正则表达式中必须加上<code>u</code>修饰符，才能识别当中的大括号，否则会被解读为量词。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/</span><span style="color:#22863A;font-weight:bold;">\\u</span><span style="color:#D73A49;">{61}</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#22863A;font-weight:bold;">\\u</span><span style="color:#D73A49;">{61}</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#22863A;font-weight:bold;">\\u</span><span style="color:#032F62;">{20BB7}/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;𠮷&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>上面代码表示，如果不加<code>u</code>修饰符，正则表达式无法识别<code>\\u{61}</code>这种表示法，只会认为这匹配 61 个连续的<code>u</code>。</p><p><strong>（3）量词</strong></p><p>使用<code>u</code>修饰符后，所有量词都会正确识别码点大于<code>0xFFFF</code>的 Unicode 字符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/a</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;aa&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#032F62;">/a</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;aa&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#032F62;">/𠮷</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;𠮷𠮷&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span>
<span class="line"><span style="color:#032F62;">/𠮷</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;𠮷𠮷&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>（4）预定义模式</strong></p><p><code>u</code>修饰符也影响到预定义模式，能否正确识别码点大于<code>0xFFFF</code>的 Unicode 字符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">\\S</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;𠮷&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">\\S</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;𠮷&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码的<code>\\S</code>是预定义模式，匹配所有不是空格的字符。只有加了<code>u</code>修饰符，它才能正确匹配码点大于<code>0xFFFF</code>的 Unicode 字符。</p><p>利用这一点，可以写出一个正确返回字符串长度的函数。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> codePointLength</span><span style="color:#24292E;">(</span><span style="color:#E36209;">text</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  var</span><span style="color:#24292E;"> result </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> text.</span><span style="color:#6F42C1;">match</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/</span><span style="color:#005CC5;">[\\s\\S]</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">gu</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#24292E;"> result </span><span style="color:#D73A49;">?</span><span style="color:#24292E;"> result.</span><span style="color:#005CC5;">length</span><span style="color:#D73A49;"> :</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> s </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;𠮷𠮷&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">s.</span><span style="color:#005CC5;">length</span><span style="color:#6A737D;"> // 4</span></span>
<span class="line"><span style="color:#6F42C1;">codePointLength</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// 2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>（5）i 修饰符</strong></p><p>有些 Unicode 字符的编码不同，但是字型很相近，比如，<code>\\u004B</code>与<code>\\u212A</code>都是大写的<code>K</code>。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/</span><span style="color:#005CC5;">[a-z]</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">i</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;</span><span style="color:#005CC5;">\\u212A</span><span style="color:#032F62;">&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#005CC5;">[a-z]</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">iu</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;</span><span style="color:#005CC5;">\\u212A</span><span style="color:#032F62;">&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，不加<code>u</code>修饰符，就无法识别非规范的<code>K</code>字符。</p><h2 id="y-修饰符" tabindex="-1">y 修饰符 <a class="header-anchor" href="#y-修饰符" aria-label="Permalink to &quot;y 修饰符&quot;">​</a></h2><p>除了<code>u</code>修饰符，ES6 还为正则表达式添加了<code>y</code>修饰符，叫做“粘连”（sticky）修饰符。</p><p><code>y</code>修饰符的作用与<code>g</code>修饰符类似，也是全局匹配，后一次匹配都从上一次匹配成功的下一个位置开始。不同之处在于，<code>g</code>修饰符只要剩余位置中存在匹配就可，而<code>y</code>修饰符确保匹配必须从剩余的第一个位置开始，这也就是“粘连”的涵义。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> s </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;aaa_aa_a&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> r1 </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /a</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> r2 </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /a</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">r1.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// [&quot;aaa&quot;]</span></span>
<span class="line"><span style="color:#24292E;">r2.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// [&quot;aaa&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">r1.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// [&quot;aa&quot;]</span></span>
<span class="line"><span style="color:#24292E;">r2.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// null</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>上面代码有两个正则表达式，一个使用<code>g</code>修饰符，另一个使用<code>y</code>修饰符。这两个正则表达式各执行了两次，第一次执行的时候，两者行为相同，剩余字符串都是<code>_aa_a</code>。由于<code>g</code>修饰没有位置要求，所以第二次执行会返回结果，而<code>y</code>修饰符要求匹配必须从头部开始，所以返回<code>null</code>。</p><p>如果改一下正则表达式，保证每次都能头部匹配，<code>y</code>修饰符就会返回结果了。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> s </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;aaa_aa_a&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> r </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /a</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">_/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">r.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// [&quot;aaa_&quot;]</span></span>
<span class="line"><span style="color:#24292E;">r.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(s) </span><span style="color:#6A737D;">// [&quot;aa_&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>上面代码每次匹配，都是从剩余字符串的头部开始。</p><p>使用<code>lastIndex</code>属性，可以更好地说明<code>y</code>修饰符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> REGEX</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /a/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 指定从2号位置（y）开始匹配</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.lastIndex </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 2</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 匹配成功</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> match</span><span style="color:#D73A49;"> =</span><span style="color:#005CC5;"> REGEX</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xaya&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 在3号位置匹配成功</span></span>
<span class="line"><span style="color:#24292E;">match.index </span><span style="color:#6A737D;">// 3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 下一次匹配从4号位开始</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.lastIndex </span><span style="color:#6A737D;">// 4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 4号位开始匹配失败</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xaxa&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// null</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>上面代码中，<code>lastIndex</code>属性指定每次搜索的开始位置，<code>g</code>修饰符从这个位置开始向后搜索，直到发现匹配为止。</p><p><code>y</code>修饰符同样遵守<code>lastIndex</code>属性，但是要求必须在<code>lastIndex</code>指定的位置发现匹配。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> REGEX</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /a/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 指定从2号位置开始匹配</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.lastIndex </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 2</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 不是粘连，匹配失败</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xaya&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// null</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 指定从3号位置开始匹配</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.lastIndex </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 3</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 3号位置是粘连，匹配成功</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> match</span><span style="color:#D73A49;"> =</span><span style="color:#005CC5;"> REGEX</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;xaxa&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">match.index </span><span style="color:#6A737D;">// 3</span></span>
<span class="line"><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">.lastIndex </span><span style="color:#6A737D;">// 4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>实际上，<code>y</code>修饰符号隐含了头部匹配的标志<code>^</code>。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/b/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;aba&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// null</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码由于不能保证头部匹配，所以返回<code>null</code>。<code>y</code>修饰符的设计本意，就是让头部匹配的标志<code>^</code>在全局匹配中都有效。</p><p>在<code>split</code>方法中使用<code>y</code>修饰符，原字符串必须以分隔符开头。这也意味着，只要匹配成功，数组的第一个成员肯定是空字符串。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 没有找到匹配</span></span>
<span class="line"><span style="color:#032F62;">&#39;x##&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">split</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/#/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;x##&#39; ]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 找到两个匹配</span></span>
<span class="line"><span style="color:#032F62;">&#39;##x&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">split</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/#/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;&#39;, &#39;&#39;, &#39;x&#39; ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>后续的分隔符只有紧跟前面的分隔符，才会被识别。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;#x#&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">split</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/#/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;&#39;, &#39;x#&#39; ]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#032F62;">&#39;##&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">split</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/#/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;&#39;, &#39;&#39;, &#39;&#39; ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>下面是字符串对象的<code>replace</code>方法的例子。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> REGEX</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /a/</span><span style="color:#D73A49;">gy</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#032F62;">&#39;aaxa&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">REGEX</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;-&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// &#39;--xa&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，最后一个<code>a</code>因为不是出现在下一次匹配的头部，所以不会被替换。</p><p>单单一个<code>y</code>修饰符对<code>match</code>方法，只能返回第一个匹配，必须与<code>g</code>修饰符联用，才能返回所有匹配。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;a1a2a3&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">match</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/a</span><span style="color:#005CC5;">\\d</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// [&quot;a1&quot;]</span></span>
<span class="line"><span style="color:#032F62;">&#39;a1a2a3&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">match</span><span style="color:#24292E;">(</span><span style="color:#032F62;">/a</span><span style="color:#005CC5;">\\d</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">gy</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// [&quot;a1&quot;, &quot;a2&quot;, &quot;a3&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>y</code>修饰符的一个应用，是从字符串提取 token（词元），<code>y</code>修饰符确保了匹配之间不会有漏掉的字符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> TOKEN_Y</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#005CC5;">\\s</span><span style="color:#D73A49;">*</span><span style="color:#032F62;">(</span><span style="color:#22863A;font-weight:bold;">\\+</span><span style="color:#D73A49;">|</span><span style="color:#005CC5;">[0-9]</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)</span><span style="color:#005CC5;">\\s</span><span style="color:#D73A49;">*</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> TOKEN_G</span><span style="color:#D73A49;">  =</span><span style="color:#032F62;"> /</span><span style="color:#005CC5;">\\s</span><span style="color:#D73A49;">*</span><span style="color:#032F62;">(</span><span style="color:#22863A;font-weight:bold;">\\+</span><span style="color:#D73A49;">|</span><span style="color:#005CC5;">[0-9]</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)</span><span style="color:#005CC5;">\\s</span><span style="color:#D73A49;">*</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">tokenize</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">TOKEN_Y</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;3 + 4&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;3&#39;, &#39;+&#39;, &#39;4&#39; ]</span></span>
<span class="line"><span style="color:#6F42C1;">tokenize</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">TOKEN_G</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;3 + 4&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;3&#39;, &#39;+&#39;, &#39;4&#39; ]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> tokenize</span><span style="color:#24292E;">(</span><span style="color:#E36209;">TOKEN_REGEX</span><span style="color:#24292E;">, </span><span style="color:#E36209;">str</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> result </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> [];</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> match;</span></span>
<span class="line"><span style="color:#D73A49;">  while</span><span style="color:#24292E;"> (match </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> TOKEN_REGEX</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(str)) {</span></span>
<span class="line"><span style="color:#24292E;">    result.</span><span style="color:#6F42C1;">push</span><span style="color:#24292E;">(match[</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">]);</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#24292E;"> result;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>上面代码中，如果字符串里面没有非法字符，<code>y</code>修饰符与<code>g</code>修饰符的提取结果是一样的。但是，一旦出现非法字符，两者的行为就不一样了。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">tokenize</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">TOKEN_Y</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;3x + 4&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;3&#39; ]</span></span>
<span class="line"><span style="color:#6F42C1;">tokenize</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">TOKEN_G</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;3x + 4&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// [ &#39;3&#39;, &#39;+&#39;, &#39;4&#39; ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>上面代码中，<code>g</code>修饰符会忽略非法字符，而<code>y</code>修饰符不会，这样就很容易发现错误。</p><h2 id="sticky-属性" tabindex="-1">sticky 属性 <a class="header-anchor" href="#sticky-属性" aria-label="Permalink to &quot;sticky 属性&quot;">​</a></h2><p>与<code>y</code>修饰符相匹配，ES6 的正则对象多了<code>sticky</code>属性，表示是否设置了<code>y</code>修饰符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> r </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /hello</span><span style="color:#005CC5;">\\d</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">y</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">r.sticky </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="flags-属性" tabindex="-1">flags 属性 <a class="header-anchor" href="#flags-属性" aria-label="Permalink to &quot;flags 属性&quot;">​</a></h2><p>ES6 为正则表达式新增了<code>flags</code>属性，会返回正则表达式的修饰符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// ES5 的 source 属性</span></span>
<span class="line"><span style="color:#6A737D;">// 返回正则表达式的正文</span></span>
<span class="line"><span style="color:#032F62;">/abc/</span><span style="color:#D73A49;">ig</span><span style="color:#24292E;">.source</span></span>
<span class="line"><span style="color:#6A737D;">// &quot;abc&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// ES6 的 flags 属性</span></span>
<span class="line"><span style="color:#6A737D;">// 返回正则表达式的修饰符</span></span>
<span class="line"><span style="color:#032F62;">/abc/</span><span style="color:#D73A49;">ig</span><span style="color:#24292E;">.flags</span></span>
<span class="line"><span style="color:#6A737D;">// &#39;gi&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="s-修饰符-dotall-模式" tabindex="-1">s 修饰符：dotAll 模式 <a class="header-anchor" href="#s-修饰符-dotall-模式" aria-label="Permalink to &quot;s 修饰符：dotAll 模式&quot;">​</a></h2><p>正则表达式中，点（<code>.</code>）是一个特殊字符，代表任意的单个字符，但是行终止符（line terminator character）除外。</p><p>以下四个字符属于”行终止符“。</p><ul><li>U+000A 换行符（<code>\\n</code>）</li><li>U+000D 回车符（<code>\\r</code>）</li><li>U+2028 行分隔符（line separator）</li><li>U+2029 段分隔符（paragraph separator）</li></ul><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/foo</span><span style="color:#005CC5;">.</span><span style="color:#032F62;">bar/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">bar&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，因为<code>.</code>不匹配<code>\\n</code>，所以正则表达式返回<code>false</code>。</p><p>但是，很多时候我们希望匹配的是任意单个字符，这时有一种变通的写法。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/foo</span><span style="color:#005CC5;">[</span><span style="color:#D73A49;">^</span><span style="color:#005CC5;">]</span><span style="color:#032F62;">bar/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">bar&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这种解决方案毕竟不太符合直觉，所以现在有一个<a href="https://github.com/mathiasbynens/es-regexp-dotall-flag" target="_blank" rel="noreferrer">提案</a>，引入<code>/s</code>修饰符，使得<code>.</code>可以匹配任意单个字符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/foo</span><span style="color:#005CC5;">.</span><span style="color:#032F62;">bar/</span><span style="color:#D73A49;">s</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">bar&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这被称为<code>dotAll</code>模式，即点（dot）代表一切字符。所以，正则表达式还引入了一个<code>dotAll</code>属性，返回一个布尔值，表示该正则表达式是否处在<code>dotAll</code>模式。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> re</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /foo</span><span style="color:#005CC5;">.</span><span style="color:#032F62;">bar/</span><span style="color:#D73A49;">s</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6A737D;">// 另一种写法</span></span>
<span class="line"><span style="color:#6A737D;">// const re = new RegExp(&#39;foo.bar&#39;, &#39;s&#39;);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">re.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">bar&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#24292E;">re.dotAll </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#24292E;">re.flags </span><span style="color:#6A737D;">// &#39;s&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>/s</code>修饰符和多行修饰符<code>/m</code>不冲突，两者一起使用的情况下，<code>.</code>匹配所有字符，而<code>^</code>和<code>$</code>匹配每一行的行首和行尾。</p><h2 id="后行断言" tabindex="-1">后行断言 <a class="header-anchor" href="#后行断言" aria-label="Permalink to &quot;后行断言&quot;">​</a></h2><p>JavaScript 语言的正则表达式，只支持先行断言（lookahead）和先行否定断言（negative lookahead），不支持后行断言（lookbehind）和后行否定断言（negative lookbehind）。目前，有一个<a href="https://github.com/goyakin/es-regexp-lookbehind" target="_blank" rel="noreferrer">提案</a>，引入后行断言，V8 引擎 4.9 版已经支持。</p><p>”先行断言“指的是，<code>x</code>只有在<code>y</code>前面才匹配，必须写成<code>/x(?=y)/</code>。比如，只匹配百分号之前的数字，要写成<code>/\\d+(?=%)/</code>。”先行否定断言“指的是，<code>x</code>只有不在<code>y</code>前面才匹配，必须写成<code>/x(?!y)/</code>。比如，只匹配不在百分号之前的数字，要写成<code>/\\d+(?!%)/</code>。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">(?=%)/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;100% of US presidents have been male&#39;</span><span style="color:#24292E;">)  </span><span style="color:#6A737D;">// [&quot;100&quot;]</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">(?!%)/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;that’s all 44 of them&#39;</span><span style="color:#24292E;">)                 </span><span style="color:#6A737D;">// [&quot;44&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面两个字符串，如果互换正则表达式，就不会得到相同结果。另外，还可以看到，”先行断言“括号之中的部分（<code>(?=%)</code>），是不计入返回结果的。</p><p>“后行断言”正好与“先行断言”相反，<code>x</code>只有在<code>y</code>后面才匹配，必须写成<code>/(?&lt;=y)x/</code>。比如，只匹配美元符号之后的数字，要写成<code>/(?&lt;=\\$)\\d+/</code>。”后行否定断言“则与”先行否定断言“相反，<code>x</code>只有不在<code>y</code>后面才匹配，必须写成<code>/(?&lt;!y)x/</code>。比如，只匹配不在美元符号后面的数字，要写成<code>/(?&lt;!\\$)\\d+/</code>。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/(?&lt;=</span><span style="color:#22863A;font-weight:bold;">\\$</span><span style="color:#032F62;">)</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;Benjamin Franklin is on the $100 bill&#39;</span><span style="color:#24292E;">)  </span><span style="color:#6A737D;">// [&quot;100&quot;]</span></span>
<span class="line"><span style="color:#032F62;">/(?&lt;!</span><span style="color:#22863A;font-weight:bold;">\\$</span><span style="color:#032F62;">)</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;it’s is worth about €90&#39;</span><span style="color:#24292E;">)                </span><span style="color:#6A737D;">// [&quot;90&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面的例子中，“后行断言”的括号之中的部分（<code>(?&lt;=\\$)</code>），也是不计入返回结果。</p><p>下面的例子是使用后行断言进行字符串替换。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_DOLLAR_PREFIX</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /(?&lt;=</span><span style="color:#22863A;font-weight:bold;">\\$</span><span style="color:#032F62;">)foo/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#032F62;">&#39;$foo %foo foo&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">RE_DOLLAR_PREFIX</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;bar&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// &#39;$bar %foo foo&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>上面代码中，只有在美元符号后面的<code>foo</code>才会被替换。</p><p>“后行断言”的实现，需要先匹配<code>/(?&lt;=y)x/</code>的<code>x</code>，然后再回到左边，匹配<code>y</code>的部分。这种“先右后左”的执行顺序，与所有其他正则操作相反，导致了一些不符合预期的行为。</p><p>首先，”后行断言“的组匹配，与正常情况下结果是不一样的。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/(?&lt;=(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">))</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;1053&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// [&quot;&quot;, &quot;1&quot;, &quot;053&quot;]</span></span>
<span class="line"><span style="color:#032F62;">/</span><span style="color:#D73A49;">^</span><span style="color:#032F62;">(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;1053&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// [&quot;1053&quot;, &quot;105&quot;, &quot;3&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，需要捕捉两个组匹配。没有&quot;后行断言&quot;时，第一个括号是贪婪模式，第二个括号只能捕获一个字符，所以结果是<code>105</code>和<code>3</code>。而&quot;后行断言&quot;时，由于执行顺序是从右到左，第二个括号是贪婪模式，第一个括号只能捕获一个字符，所以结果是<code>1</code>和<code>053</code>。</p><p>其次，&quot;后行断言&quot;的反斜杠引用，也与通常的顺序相反，必须放在对应的那个括号之前。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">/(?&lt;=(o)d</span><span style="color:#D73A49;">\\1</span><span style="color:#032F62;">)r/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;hodor&#39;</span><span style="color:#24292E;">)  </span><span style="color:#6A737D;">// null</span></span>
<span class="line"><span style="color:#032F62;">/(?&lt;=</span><span style="color:#D73A49;">\\1</span><span style="color:#032F62;">d(o))r/</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;hodor&#39;</span><span style="color:#24292E;">)  </span><span style="color:#6A737D;">// [&quot;r&quot;, &quot;o&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，如果后行断言的反斜杠引用（<code>\\1</code>）放在括号的后面，就不会得到匹配结果，必须放在前面才可以。因为后行断言是先从左到右扫描，发现匹配以后再回过头，从右到左完成反斜杠引用。</p><h2 id="unicode-属性类" tabindex="-1">Unicode 属性类 <a class="header-anchor" href="#unicode-属性类" aria-label="Permalink to &quot;Unicode 属性类&quot;">​</a></h2><p>目前，有一个<a href="https://github.com/mathiasbynens/es-regexp-unicode-property-escapes" target="_blank" rel="noreferrer">提案</a>，引入了一种新的类的写法<code>\\p{...}</code>和<code>\\P{...}</code>，允许正则表达式匹配符合 Unicode 某种属性的所有字符。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regexGreekSymbol</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#22863A;font-weight:bold;">\\p</span><span style="color:#032F62;">{Script=Greek}/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">regexGreekSymbol.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;π&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，<code>\\p{Script=Greek}</code>指定匹配一个希腊文字母，所以匹配<code>π</code>成功。</p><p>Unicode 属性类要指定属性名和属性值。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">\\p{UnicodePropertyName</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">UnicodePropertyValue}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>对于某些属性，可以只写属性名。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">\\p{UnicodePropertyName}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>\\P{…}</code>是<code>\\p{…}</code>的反向匹配，即匹配不满足条件的字符。</p><p>注意，这两种类只对 Unicode 有效，所以使用的时候一定要加上<code>u</code>修饰符。如果不加<code>u</code>修饰符，正则表达式使用<code>\\p</code>和<code>\\P</code>会报错，ECMAScript 预留了这两个类。</p><p>由于 Unicode 的各种属性非常多，所以这种新的类的表达能力非常强。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#22863A;font-weight:bold;">\\p</span><span style="color:#032F62;">{Decimal_Number}</span><span style="color:#D73A49;">+$</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">regex.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;𝟏𝟐𝟑𝟜𝟝𝟞𝟩𝟪𝟫𝟬𝟭𝟮𝟯𝟺𝟻𝟼&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上面代码中，属性类指定匹配所有十进制字符，可以看到各种字型的十进制字符都会匹配成功。</p><p><code>\\p{Number}</code>甚至能匹配罗马数字。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 匹配所有数字</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#22863A;font-weight:bold;">\\p</span><span style="color:#032F62;">{Number}</span><span style="color:#D73A49;">+$</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">regex.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;²³¹¼½¾&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#24292E;">regex.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;㉛㉜㉝&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#24292E;">regex.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;ⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩⅪⅫ&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>下面是其他一些例子。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 匹配各种文字的所有字母，等同于 Unicode 版的 \\w</span></span>
<span class="line"><span style="color:#24292E;">[\\p{Alphabetic}\\p{Mark}\\p{Decimal_Number}\\p{Connector_Punctuation}\\p{Join_Control}]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 匹配各种文字的所有非字母的字符，等同于 Unicode 版的 \\W</span></span>
<span class="line"><span style="color:#24292E;">[</span><span style="color:#D73A49;">^</span><span style="color:#24292E;">\\p{Alphabetic}\\p{Mark}\\p{Decimal_Number}\\p{Connector_Punctuation}\\p{Join_Control}]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 匹配所有的箭头字符</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regexArrows</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#22863A;font-weight:bold;">\\p</span><span style="color:#032F62;">{Block=Arrows}</span><span style="color:#D73A49;">+$</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">regexArrows.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;←↑→↓↔↕↖↗↘↙⇏⇐⇑⇒⇓⇔⇕⇖⇗⇘⇙⇧⇩&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="具名组匹配" tabindex="-1">具名组匹配 <a class="header-anchor" href="#具名组匹配" aria-label="Permalink to &quot;具名组匹配&quot;">​</a></h2><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h3><p>正则表达式使用圆括号进行组匹配。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_DATE</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{4}</span><span style="color:#032F62;">)-(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)-(</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)/</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>上面代码中，正则表达式里面有三组圆括号。使用<code>exec</code>方法，就可以将这三组匹配结果提取出来。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> matchObj</span><span style="color:#D73A49;"> =</span><span style="color:#005CC5;"> RE_DATE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;1999-12-31&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> year</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> matchObj[</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">]; </span><span style="color:#6A737D;">// 1999</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> month</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> matchObj[</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">]; </span><span style="color:#6A737D;">// 12</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> day</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> matchObj[</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">]; </span><span style="color:#6A737D;">// 31</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>组匹配的一个问题是，每一组的匹配含义不容易看出来，而且只能用数字序号引用，要是组的顺序变了，引用的时候就必须修改序号。</p><p>现在有一个“具名组匹配”（Named Capture Groups）的<a href="https://github.com/tc39/proposal-regexp-named-groups" target="_blank" rel="noreferrer">提案</a>，允许为每一个组匹配指定一个名字，既便于阅读代码，又便于引用。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_DATE</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /(?&lt;</span><span style="color:#24292E;">year</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{4}</span><span style="color:#032F62;">)-(?&lt;</span><span style="color:#24292E;">month</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)-(?&lt;</span><span style="color:#24292E;">day</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)/</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> matchObj</span><span style="color:#D73A49;"> =</span><span style="color:#005CC5;"> RE_DATE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;1999-12-31&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> year</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> matchObj.groups.year; </span><span style="color:#6A737D;">// 1999</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> month</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> matchObj.groups.month; </span><span style="color:#6A737D;">// 12</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> day</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> matchObj.groups.day; </span><span style="color:#6A737D;">// 31</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>上面代码中，“具名组匹配”在圆括号内部，模式的头部添加“问号 + 尖括号 + 组名”（<code>?&lt;year&gt;</code>），然后就可以在<code>exec</code>方法返回结果的<code>groups</code>属性上引用该组名。同时，数字序号（<code>matchObj[1]</code>）依然有效。</p><p>具名组匹配等于为每一组匹配加上了 ID，便于描述匹配的目的。如果组的顺序变了，也不用改变匹配后的处理代码。</p><p>如果具名组没有匹配，那么对应的<code>groups</code>对象属性会是<code>undefined</code>。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_OPT_A</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#032F62;">(?&lt;</span><span style="color:#24292E;">as</span><span style="color:#032F62;">&gt;a</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)</span><span style="color:#D73A49;">?$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> matchObj</span><span style="color:#D73A49;"> =</span><span style="color:#005CC5;"> RE_OPT_A</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">matchObj.groups.as </span><span style="color:#6A737D;">// undefined</span></span>
<span class="line"><span style="color:#032F62;">&#39;as&#39;</span><span style="color:#D73A49;"> in</span><span style="color:#24292E;"> matchObj.groups </span><span style="color:#6A737D;">// true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>上面代码中，具名组<code>as</code>没有找到匹配，那么<code>matchObj.groups.as</code>属性值就是<code>undefined</code>，并且<code>as</code>这个键名在<code>groups</code>是始终存在的。</p><h3 id="解构赋值和替换" tabindex="-1">解构赋值和替换 <a class="header-anchor" href="#解构赋值和替换" aria-label="Permalink to &quot;解构赋值和替换&quot;">​</a></h3><p>有了具名组匹配以后，可以使用解构赋值直接从匹配结果上为变量赋值。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> {</span><span style="color:#E36209;">groups</span><span style="color:#24292E;">: {one, two}} </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#032F62;">(?&lt;</span><span style="color:#24292E;">one</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">.</span><span style="color:#D73A49;">*</span><span style="color:#032F62;">):(?&lt;</span><span style="color:#24292E;">two</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">.</span><span style="color:#D73A49;">*</span><span style="color:#032F62;">)</span><span style="color:#D73A49;">$</span><span style="color:#032F62;">/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">exec</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo:bar&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">one  </span><span style="color:#6A737D;">// foo</span></span>
<span class="line"><span style="color:#24292E;">two  </span><span style="color:#6A737D;">// bar</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>字符串替换时，使用<code>$&lt;组名&gt;</code>引用具名组。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> re </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> /(?&lt;</span><span style="color:#24292E;">year</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{4}</span><span style="color:#032F62;">)-(?&lt;</span><span style="color:#24292E;">month</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)-(?&lt;</span><span style="color:#24292E;">day</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">\\d</span><span style="color:#D73A49;">{2}</span><span style="color:#032F62;">)/</span><span style="color:#D73A49;">u</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#032F62;">&#39;2015-01-02&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(re, </span><span style="color:#032F62;">&#39;$&lt;day&gt;/$&lt;month&gt;/$&lt;year&gt;&#39;</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#6A737D;">// &#39;02/01/2015&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>上面代码中，<code>replace</code>方法的第二个参数是一个字符串，而不是正则表达式。</p><p><code>replace</code>方法的第二个参数也可以是函数，该函数的参数序列如下。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&#39;2015-01-02&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">replace</span><span style="color:#24292E;">(re, (</span></span>
<span class="line"><span style="color:#E36209;">   matched</span><span style="color:#24292E;">, </span><span style="color:#6A737D;">// 整个匹配结果 2015-01-02</span></span>
<span class="line"><span style="color:#E36209;">   capture1</span><span style="color:#24292E;">, </span><span style="color:#6A737D;">// 第一个组匹配 2015</span></span>
<span class="line"><span style="color:#E36209;">   capture2</span><span style="color:#24292E;">, </span><span style="color:#6A737D;">// 第二个组匹配 01</span></span>
<span class="line"><span style="color:#E36209;">   capture3</span><span style="color:#24292E;">, </span><span style="color:#6A737D;">// 第三个组匹配 02</span></span>
<span class="line"><span style="color:#E36209;">   position</span><span style="color:#24292E;">, </span><span style="color:#6A737D;">// 匹配开始的位置 0</span></span>
<span class="line"><span style="color:#E36209;">   S</span><span style="color:#24292E;">, </span><span style="color:#6A737D;">// 原字符串 2015-01-02</span></span>
<span class="line"><span style="color:#24292E;">   groups </span><span style="color:#6A737D;">// 具名组构成的一个对象 {year, month, day}</span></span>
<span class="line"><span style="color:#24292E;"> ) </span><span style="color:#D73A49;">=&gt;</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#D73A49;"> let</span><span style="color:#24292E;"> {day, month, year} </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> args[args.</span><span style="color:#005CC5;">length</span><span style="color:#D73A49;"> -</span><span style="color:#005CC5;"> 1</span><span style="color:#24292E;">];</span></span>
<span class="line"><span style="color:#D73A49;"> return</span><span style="color:#032F62;"> \`\${</span><span style="color:#24292E;">day</span><span style="color:#032F62;">}/\${</span><span style="color:#24292E;">month</span><span style="color:#032F62;">}/\${</span><span style="color:#24292E;">year</span><span style="color:#032F62;">}\`</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>具名组匹配在原来的基础上，新增了最后一个函数参数：具名组构成的一个对象。函数内部可以直接对这个对象进行解构赋值。</p><h3 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h3><p>如果要在正则表达式内部引用某个“具名组匹配”，可以使用<code>\\k&lt;组名&gt;</code>的写法。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_TWICE</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#032F62;">(?&lt;</span><span style="color:#24292E;">word</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">[a-z]</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)!</span><span style="color:#D73A49;">\\k&lt;</span><span style="color:#24292E;">word</span><span style="color:#D73A49;">&gt;$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#005CC5;">RE_TWICE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;abc!abc&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#005CC5;">RE_TWICE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;abc!ab&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>数字引用（<code>\\1</code>）依然有效。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_TWICE</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#032F62;">(?&lt;</span><span style="color:#24292E;">word</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">[a-z]</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)!</span><span style="color:#D73A49;">\\1$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#005CC5;">RE_TWICE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;abc!abc&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#005CC5;">RE_TWICE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;abc!ab&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这两种引用语法还可以同时使用。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> RE_TWICE</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /</span><span style="color:#D73A49;">^</span><span style="color:#032F62;">(?&lt;</span><span style="color:#24292E;">word</span><span style="color:#032F62;">&gt;</span><span style="color:#005CC5;">[a-z]</span><span style="color:#D73A49;">+</span><span style="color:#032F62;">)!</span><span style="color:#D73A49;">\\k&lt;</span><span style="color:#24292E;">word</span><span style="color:#D73A49;">&gt;</span><span style="color:#032F62;">!</span><span style="color:#D73A49;">\\1$</span><span style="color:#032F62;">/</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#005CC5;">RE_TWICE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;abc!abc!abc&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#005CC5;">RE_TWICE</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">test</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;abc!abc!ab&#39;</span><span style="color:#24292E;">) </span><span style="color:#6A737D;">// false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,156)])])}const u=a(e,[["render",o]]);export{b as __pageData,u as default};
